1	// Cold Email Engine — warmup + deliverability rollup / auto-pause sweeps (Phase 3).
2	//
3	// Two background passes, both safe to run regardless of the send kill-switch
4	// because NEITHER sends mail — they maintain warmup state and roll DeliverabilityEvent
5	// rows into MetricsDaily / HealthSnapshot, then AUTO-PAUSE inboxes/domains whose
6	// bounce or complaint rate crossed a burn threshold (research §4). All queries are
7	// tolerant of un-migrated tables (mirrors the send sweep).
8	
9	import { db } from "../lib/db";
10	import { getSetting } from "../lib/settings";
11	import { logEvent } from "../lib/log";
12	import { inboxAllowedVolume, warmupStatus } from "../lib/coldemail/warmup";
13	import { warmupDayIndex } from "../lib/coldemail/compliance";
14	import {
15	  resolveThresholds,
16	  evaluateInboxAutoPause,
17	  evaluateDomainAutoPause,
18	  bounceRate,
19	  complaintRate,
20	  type BurnThresholds,
21	  type RateStats,
22	} from "../lib/coldemail/rotation";
23	import { addCounts, deriveRates, healthScore, healthLevel, ZERO_COUNTS, type MetricCounts } from "../lib/coldemail/analytics";
24	import { reconcileEmailStatus } from "../lib/coldemail/leaddb";
25	import type { EmailEventType } from "@prisma/client";
26	
27	function startOfUtcDay(now = new Date()): Date {
28	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
29	}
30	
31	// ---------------------------------------------------------------------------
32	// Warmup sweep — recompute each inbox's ramp cap + today's WarmupState, and
33	// promote a fully-warmed, authenticated inbox from WARMING → ACTIVE.
34	// ---------------------------------------------------------------------------
35	
36	export async function coldEmailWarmupSweep(): Promise<void> {
37	  let inboxes;
38	  try {
39	    inboxes = await db.inbox.findMany({
40	      where: { status: { in: ["WARMING", "ACTIVE"] } },
41	      include: { sendingDomain: { select: { spfVerified: true, dkimVerified: true, dmarcVerified: true } } },
42	    });
43	  } catch {
44	    return; // tables not migrated on this env
45	  }
46	
47	  const now = new Date();
48	  const day0 = startOfUtcDay(now);
49	
50	  for (const ib of inboxes) {
51	    const plan = { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays };
52	    const day = warmupDayIndex(ib.warmupStartedAt, now);
53	    const status = warmupStatus(day, plan);
54	    const currentRampCap = inboxAllowedVolume({
55	      warmupStartedAt: ib.warmupStartedAt,
56	      plan,
57	      dailyCap: ib.dailyCap,
58	      healthScore: ib.healthScore,
59	      adaptive: ib.strategy === "ADAPTIVE",
60	      now,
61	    });
62	
63	    try {
64	      await db.inbox.update({ where: { id: ib.id }, data: { warmupDay: day, currentRampCap } });
65	
66	      // Actual sends made by this inbox today (for the planned-vs-actual curve).
67	      const sentVolume = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: day0 } } });
68	      await db.warmupState.upsert({
69	        where: { inboxId_date: { inboxId: ib.id, date: day0 } },
70	        create: {
71	          inboxId: ib.id,
72	          date: day0,
73	          day,
74	          plannedVolume: currentRampCap,
75	          sentVolume,
76	          healthScore: ib.healthScore,
77	        },
78	        update: { day, plannedVolume: currentRampCap, sentVolume, healthScore: ib.healthScore },
79	      });
80	
81	      // Promote a warmed + authenticated inbox to ACTIVE (rotation-eligible). We only
82	      // auto-promote; we never auto-pause here (that's the rollup sweep's job).
83	      const d = ib.sendingDomain;
84	      const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
85	      if (ib.status === "WARMING" && status.complete && authGreen) {
86	        await db.inbox.update({ where: { id: ib.id }, data: { status: "ACTIVE", pausedReason: "" } });
87	        await logEvent("info", "coldemail.warmup.complete", { inboxId: ib.id, day });
88	      }
89	    } catch (err) {
90	      await logEvent("error", "coldemail.warmup.sweep", { inboxId: ib.id, message: String(err) });
91	    }
92	  }
93	}
94	
95	// ---------------------------------------------------------------------------
96	// Rollup + auto-pause sweep
97	// ---------------------------------------------------------------------------
98	
99	const EVENT_TO_COUNT: Record<string, Partial<MetricCounts>> = {
100	  SENT: { sent: 1 },
101	  DELIVERED: { delivered: 1 },
102	  HARD_BOUNCE: { hardBounce: 1 },
103	  SOFT_BOUNCE: { softBounce: 1 },
104	  OPEN: { opens: 1 },
105	  CLICK: { uniqueClicks: 1 },
106	  REPLY: { replies: 1 },
107	  POSITIVE_REPLY: { positiveReplies: 1, replies: 1 },
108	  COMPLAINT: { complaints: 1 },
109	  UNSUBSCRIBE: { unsubscribes: 1 },
110	};
111	
112	type Grouped = Map<string, MetricCounts>;
113	
114	function bump(map: Grouped, key: string | null | undefined, delta: Partial<MetricCounts>): void {
115	  if (!key) return;
116	  map.set(key, addCounts(map.get(key) ?? ZERO_COUNTS, delta));
117	}
118	
119	async function upsertMetrics(scope: "INBOX" | "DOMAIN" | "CAMPAIGN" | "BRAND", date: Date, map: Grouped): Promise<void> {
120	  for (const [scopeId, c] of map) {
121	    await db.metricsDaily
122	      .upsert({
123	        where: { scope_scopeId_date: { scope, scopeId, date } },
124	        create: { scope, scopeId, date, ...c },
125	        update: { ...c },
126	      })
127	      .catch(() => null);
128	  }
129	}
130	
131	/** Aggregate this UTC day's DeliverabilityEvent rows into MetricsDaily by scope. */
132	export async function coldEmailRollupSweep(): Promise<void> {
133	  const now = new Date();
134	  const day0 = startOfUtcDay(now);
135	
136	  let events;
137	  try {
138	    events = await db.deliverabilityEvent.findMany({
139	      where: { occurredAt: { gte: day0 } },
140	      select: { type: true, inboxId: true, sendingDomainId: true, campaignId: true },
141	    });
142	  } catch {
143	    return; // not migrated
144	  }
145	
146	  const byInbox: Grouped = new Map();
147	  const byDomain: Grouped = new Map();
148	  const byCampaign: Grouped = new Map();
149	  const brandByDomain = new Map<string, string>();
150	
151	  for (const e of events) {
152	    const delta = EVENT_TO_COUNT[e.type];
153	    if (!delta) continue;
154	    bump(byInbox, e.inboxId, delta);
155	    bump(byDomain, e.sendingDomainId, delta);
156	    bump(byCampaign, e.campaignId, delta);
157	  }
158	
159	  try {
160	    await upsertMetrics("INBOX", day0, byInbox);
161	    await upsertMetrics("DOMAIN", day0, byDomain);
162	    await upsertMetrics("CAMPAIGN", day0, byCampaign);
163	  } catch (err) {
164	    await logEvent("error", "coldemail.rollup.upsert", { message: String(err) });
165	  }
166	
167	  // Roll domains up to their brand for the agency/multi-client view.
168	  const byBrand: Grouped = new Map();
169	  for (const [domainId, c] of byDomain) {
170	    let brandId = brandByDomain.get(domainId);
171	    if (!brandId) {
172	      const d = await db.sendingDomain.findUnique({ where: { id: domainId }, select: { brandId: true } }).catch(() => null);
173	      brandId = d?.brandId;
174	      if (brandId) brandByDomain.set(domainId, brandId);
175	    }
176	    if (brandId) bump(byBrand, brandId, c);
177	  }
178	  await upsertMetrics("BRAND", day0, byBrand).catch(() => null);
179	
180	  // Auto-pause pass over the trailing window.
181	  const thresholds = await loadThresholds();
182	  await evaluateInboxes(thresholds);
183	  await evaluateDomains(thresholds);
184	
185	  // LEAD-DB: reconcile contact email-health from bounce/complaint events.
186	  await coldEmailHygieneSweep().catch(() => null);
187	}
188	
189	// ---------------------------------------------------------------------------
190	// LEAD-DB hygiene reconciliation sweep
191	// ---------------------------------------------------------------------------
192	
193	const ADVERSE_EVENT_TYPES = ["HARD_BOUNCE", "SOFT_BOUNCE", "BOUNCE", "COMPLAINT", "UNSUBSCRIBE"] as const;
194	
195	/**
196	 * Idempotently recompute each contact's emailStatus from the FULL aggregate of its
197	 * lifetime adverse EmailEvents, so a bounce/complaint that arrived by any path
198	 * (feedback route, SNS, manual entry) is reflected on the contact — and a
199	 * permanent bounce sets HARD_BOUNCED + a GLOBAL suppression. Scoped to contacts
200	 * with a recent adverse event so the sweep stays cheap. Never throws.
201	 */
202	export async function coldEmailHygieneSweep(sinceDays = 3): Promise<void> {
203	  const threshold = await softBounceDeadThreshold();
204	  const since = new Date(Date.now() - sinceDays * 86_400_000);
205	
206	  let recent;
207	  try {
208	    recent = await db.emailEvent.findMany({
209	      where: { type: { in: ADVERSE_EVENT_TYPES as unknown as EmailEventType[] }, createdAt: { gte: since } },
210	      select: { send: { select: { contactId: true } } },
211	    });
212	  } catch {
213	    return; // not migrated
214	  }
215	
216	  const contactIds = Array.from(new Set(recent.map((e) => e.send?.contactId).filter((x): x is string => !!x)));
217	  for (const contactId of contactIds) {
218	    try {
219	      await reconcileOneContact(contactId, threshold);
220	    } catch (err) {
221	      await logEvent("error", "coldemail.hygiene.reconcile", { contactId, message: String(err) });
222	    }
223	  }
224	}
225	
226	async function reconcileOneContact(contactId: string, threshold: number): Promise<void> {
227	  const contact = await db.contact.findUnique({
228	    where: { id: contactId },
229	    select: { id: true, email: true, emailStatus: true, bounceCount: true },
230	  });
231	  if (!contact) return;
232	
233	  // Aggregate this contact's lifetime adverse events (legacy BOUNCE counts as hard).
234	  const rows = await db.emailEvent.groupBy({
235	    by: ["type"],
236	    where: { type: { in: ADVERSE_EVENT_TYPES as unknown as EmailEventType[] }, send: { contactId } },
237	    _count: { _all: true },
238	  });
239	  const counts = { hardBounce: 0, softBounce: 0, complaint: 0, unsubscribe: 0 };
240	  for (const r of rows as { type: string; _count: { _all: number } }[]) {
241	    const n = r._count._all;
242	    if (r.type === "HARD_BOUNCE" || r.type === "BOUNCE") counts.hardBounce += n;
243	    else if (r.type === "SOFT_BOUNCE") counts.softBounce += n;
244	    else if (r.type === "COMPLAINT") counts.complaint += n;
245	    else if (r.type === "UNSUBSCRIBE") counts.unsubscribe += n;
246	  }
247	
248	  const res = reconcileEmailStatus(counts, contact, threshold);
249	  if (!res.changed && !res.suppress) return;
250	
251	  if (res.changed) {
252	    await db.contact.update({
253	      where: { id: contact.id },
254	      data: {
255	        emailStatus: res.emailStatus as never,
256	        bounceCount: res.bounceCount,
257	        ...(res.dead ? { deadAt: new Date(), ...(res.deadReason ? { deadReason: res.deadReason } : {}) } : {}),
258	      },
259	    });
260	  }
261	
262	  // Ensure a GLOBAL suppression exists for a now-terminal address (idempotent).
263	  if (res.suppress && contact.email && res.suppressReason) {
264	    const existing = await db.suppression.findFirst({ where: { email: contact.email, scope: "GLOBAL" }, select: { id: true } });
265	    if (!existing) {
266	      await db.suppression.create({ data: { email: contact.email, scope: "GLOBAL", reason: res.suppressReason } }).catch(() => null);
267	    }
268	  }
269	}
270	
271	async function softBounceDeadThreshold(): Promise<number> {
272	  const n = Number(await getSetting("coldemail_soft_bounce_dead_threshold"));
273	  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 3;
274	}
275	
276	async function loadThresholds(): Promise<BurnThresholds> {
277	  const num = async (key: string) => {
278	    const v = Number(await getSetting(key));
279	    return Number.isFinite(v) && v > 0 ? v : undefined;
280	  };
281	  return resolveThresholds({
282	    bouncePauseInbox: await num("coldemail_bounce_pause_inbox"),
283	    bouncePauseDomain: await num("coldemail_bounce_pause_domain"),
284	    bounceHardStop: await num("coldemail_bounce_hard_stop"),
285	    complaintPauseDomain: await num("coldemail_complaint_pause_domain"),
286	  });
287	}
288	
289	/** RateStats for a scope over a trailing window (default 7 days). */
290	async function statsForScope(where: Record<string, unknown>, sinceDays = 7): Promise<RateStats> {
291	  const since = new Date(Date.now() - sinceDays * 86_400_000);
292	  const rows = await db.deliverabilityEvent
293	    .groupBy({ by: ["type"], where: { ...where, occurredAt: { gte: since } }, _count: { _all: true } })
294	    .catch(() => [] as { type: string; _count: { _all: number } }[]);
295	  let sent = 0,
296	    delivered = 0,
297	    bounces = 0,
298	    complaints = 0;
299	  for (const r of rows as { type: string; _count: { _all: number } }[]) {
300	    const n = r._count._all;
301	    if (r.type === "SENT") sent += n;
302	    else if (r.type === "DELIVERED") delivered += n;
303	    else if (r.type === "HARD_BOUNCE" || r.type === "SOFT_BOUNCE") bounces += n;
304	    else if (r.type === "COMPLAINT") complaints += n;
305	  }
306	  return { sent, delivered, bounces, complaints };
307	}
308	
309	async function writeHealthSnapshot(scope: "INBOX" | "DOMAIN", scopeId: string, stats: RateStats, rules: string[], paused: boolean): Promise<void> {
310	  const day0 = startOfUtcDay();
311	  const counts: MetricCounts = { ...ZERO_COUNTS, sent: stats.sent, delivered: stats.delivered, hardBounce: stats.bounces, complaints: stats.complaints };
312	  const score = healthScore(counts);
313	  const status = paused ? "PAUSED" : healthLevel(score) === "healthy" ? "HEALTHY" : healthLevel(score) === "warning" ? "WARNING" : "DANGER";
314	  await db.healthSnapshot
315	    .upsert({
316	      where: { scope_scopeId_date: { scope, scopeId, date: day0 } },
317	      create: { scope, scopeId, date: day0, healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
318	      update: { healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
319	    })
320	    .catch(() => null);
321	}
322	
323	async function evaluateInboxes(thresholds: BurnThresholds): Promise<void> {
324	  let inboxes;
325	  try {
326	    inboxes = await db.inbox.findMany({ where: { status: "ACTIVE" }, select: { id: true } });
327	  } catch {
328	    return;
329	  }
330	  for (const ib of inboxes) {
331	    const stats = await statsForScope({ inboxId: ib.id });
332	    const v = evaluateInboxAutoPause(stats, thresholds);
333	    await writeHealthSnapshot("INBOX", ib.id, stats, v.rules, v.pause);
334	    if (v.pause) {
335	      await db.inbox
336	        .update({ where: { id: ib.id }, data: { status: v.hardStop ? "BURNING" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
337	        .catch(() => null);
338	      await logEvent("warn", "coldemail.autopause.inbox", { inboxId: ib.id, rules: v.rules, bounceRate: bounceRate(stats) });
339	    }
340	  }
341	}
342	
343	async function evaluateDomains(thresholds: BurnThresholds): Promise<void> {
344	  let domains;
345	  try {
346	    domains = await db.sendingDomain.findMany({ where: { status: { in: ["ACTIVE", "WARMING"] } }, select: { id: true } });
347	  } catch {
348	    return;
349	  }
350	  for (const d of domains) {
351	    const stats = await statsForScope({ sendingDomainId: d.id });
352	    const v = evaluateDomainAutoPause(stats, thresholds);
353	    await writeHealthSnapshot("DOMAIN", d.id, stats, v.rules, v.pause);
354	    if (v.pause) {
355	      await db.sendingDomain
356	        .update({ where: { id: d.id }, data: { status: v.hardStop ? "BURNED" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
357	        .catch(() => null);
358	      // Take the domain's inboxes out of rotation too.
359	      await db.inbox.updateMany({ where: { sendingDomainId: d.id, status: "ACTIVE" }, data: { status: "PAUSED", pausedReason: "Domain auto-paused" } }).catch(() => null);
360	      await logEvent("warn", "coldemail.autopause.domain", { domainId: d.id, rules: v.rules, complaintRate: complaintRate(stats), bounceRate: bounceRate(stats) });
361	    }
362	  }
363	}
