102	/** Append a deliverability event (the analytics spine). Never throws to the caller. */
103	async function recordDeliverability(
104	  type: "SENT" | "FAILED" | "DELIVERED",
105	  ctx: { inboxId?: string | null; sendingDomainId?: string | null; campaignId: string; contactId?: string | null; sendId: string; meta?: string },
106	): Promise<void> {
107	  const t = type === "FAILED" ? "DEFERRED" : type; // FAILED maps to a soft/deferred signal
108	  try {
109	    await db.deliverabilityEvent.create({
110	      data: {
111	        type: t,
112	        inboxId: ctx.inboxId ?? null,
113	        sendingDomainId: ctx.sendingDomainId ?? null,
114	        campaignId: ctx.campaignId,
115	        contactId: ctx.contactId ?? null,
116	        sendId: ctx.sendId,
117	        meta: (ctx.meta ?? "").slice(0, 300),
118	      },
119	    });
120	  } catch {
121	    /* table not migrated / best-effort — analytics must never fail a send */
122	  }
123	}
124	
125	/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
126	const MAX_SENDS_PER_SWEEP = 50;
127	/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
128	const THROTTLE_MIN_MS = 800;
129	const THROTTLE_MAX_MS = 2600;
130	
131	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
132	const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));
133	
134	function appHost(): string | null {
135	  try {
136	    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
137	  } catch {
138	    return null;
139	  }
140	}
141	
142	function startOfUtcDay(now = new Date()): Date {
143	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
144	}
145	
146	/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
147	function minutesInTz(now: Date, tz: string): number {
148	  try {
149	    const parts = new Intl.DateTimeFormat("en-US", {
150	      timeZone: tz || "UTC",
151	      hour: "2-digit",
152	      minute: "2-digit",
153	      hour12: false,
154	    }).formatToParts(now);
155	    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
156	    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
157	    return h * 60 + m;
158	  } catch {
159	    return now.getUTCHours() * 60 + now.getUTCMinutes();
160	  }
161	}
162	
163	function withinSendWindow(
164	  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
165	  now: Date,
166	): boolean {
167	  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
168	  const cur = minutesInTz(now, c.timezone || "UTC");
169	  const s = c.sendWindowStart;
170	  const e = c.sendWindowEnd;
171	  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
172	}
173	
174	type CampaignForSend = {
175	  id: string;
176	  brandId: string;
177	  listId: string;
178	  launchedAt: Date | null;
179	  sendWindowStart: number | null;
180	  sendWindowEnd: number | null;
181	  timezone: string;
182	};
183	
184	/**
185	 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
186	 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
187	 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
188	 */
189	async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
190	  const steps = await db.sequenceStep.findMany({
191	    where: { campaignId: campaign.id },
192	    orderBy: { stepOrder: "asc" },
193	    select: { id: true, delayDays: true },
194	  });
195	  if (steps.length === 0) return;
196	
197	  const base = campaign.launchedAt ?? new Date();
198	  // Cumulative offset (days) at each step.
199	  let cumulative = 0;
200	  const stepSchedule = steps.map((s) => {
201	    cumulative += Math.max(0, s.delayDays);
202	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
203	  });
204	
205	  const members = await db.emailListMember.findMany({
206	    where: { listId: campaign.listId },
207	    select: { contactId: true, contact: { select: { email: true, emailStatus: true } } },
208	  });
209	  if (members.length === 0) return;
210	
211	  // LEAD-DB exclusion: never schedule a send for a non-mailable (dead / hard-bounced
212	  // / complained / unsubscribed) or globally/brand-suppressed contact. The send-time
213	  // suppression re-check remains as defence-in-depth for rows queued earlier.
214	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
215	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
216	    select: { email: true, domain: true, scope: true, brandId: true },
217	  });
218	
219	  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
220	  for (const m of members) {
221	    if (!isMailableStatus(m.contact?.emailStatus)) continue;
222	    if (m.contact?.email && isSuppressed(m.contact.email, campaign.brandId, suppressions)) continue;
223	    for (const s of stepSchedule) {
224	      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
225	    }
226	  }
227	  if (rows.length === 0) return;
228	  // createMany + skipDuplicates: never double-queues a message across sweeps.
229	  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
230	}
231	
232	/**
233	 * Process due sends for one eligible campaign. Returns the number actually sent so
234	 * the caller can respect the per-sweep budget across campaigns.
235	 */
236	async function processDueSends(
237	  campaign: CampaignForSend,
238	  identity: SendIdentity,
239	  ctx: {
240	    now: Date;
241	    transport: MailTransport;
242	    ceiling: number;
243	    warmupEnabled: boolean;
244	    footerDisclosure: string;
245	    budget: number;
246	  },
247	): Promise<number> {
248	  if (ctx.budget <= 0) return 0;
249	  if (!withinSendWindow(campaign, ctx.now)) return 0;
250	
251	  // ===== Phase 3 — rotation pool =====
252	  // If the brand has ACTIVE inboxes, distribute sends across them honouring each
253	  // inbox's warmup limit + dailyCap + min gap (rotation.selectNextInbox). Otherwise
254	  // fall back to the Phase 2 brand-level warmup cap (unchanged).
255	  const pool = await loadBrandRotationPool(campaign.brandId, identity, ctx.now);
256	  const useRotation = pool.length > 0;
257	  const poolById = new Map(pool.map((p) => [p.candidate.id, p]));
258	
259	  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
260	  const brand = await db.brand.findUnique({
261	    where: { id: campaign.brandId },
262	    select: { warmupStartedAt: true, dailySendCap: true },
263	  });
264	  const cap = effectiveDailyCap({
265	    warmupStartedAt: brand?.warmupStartedAt ?? null,
266	    ceiling: brand?.dailySendCap ?? ctx.ceiling,
267	    warmupEnabled: ctx.warmupEnabled,
268	    now: ctx.now,
269	  });
270	  let sentToday = await db.coldSend.count({
271	    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
272	  });
273	  if (!useRotation && sentToday >= cap) return 0;
274	
275	  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
276	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
277	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
278	    select: { email: true, domain: true, scope: true, brandId: true },
279	  });
280	
281	  const due = await db.coldSend.findMany({
282	    where: {
283	      campaignId: campaign.id,
284	      status: "QUEUED",
285	      stepId: { not: null },
286	      scheduledFor: { lte: ctx.now },
287	    },
288	    orderBy: { scheduledFor: "asc" },
289	    take: ctx.budget,
290	    include: {
291	      contact: {
292	        select: { id: true, email: true, fullName: true, title: true, firstEmailedAt: true, business: { select: { name: true } } },
293	      },
294	      step: { select: { subject: true, bodyMarkdown: true } },
295	    },
296	  });
297	
298	  let sent = 0;
299	  for (const s of due) {
300	    if (!s.step || !s.contact) continue;
301	
302	    // GUARDRAIL #4 — re-check suppression immediately before the send.
303	    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
304	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
305	      continue;
306	    }
307	
308	    // Pick the sending inbox (rotation) or fall back to the brand identity + cap.
309	    let chosen: PoolInbox | null = null;
310	    if (useRotation) {
311	      const cand = selectNextInbox(pool.map((p) => p.candidate), ctx.now);
312	      if (!cand) break; // no eligible inbox right now — leave the rest QUEUED
313	      chosen = poolById.get(cand.id) ?? null;
314	      if (!chosen) break;
315	    } else if (sentToday >= cap) {
316	      break; // brand-level cap reached
317	    }
318	
319	    const sendIdentity = chosen ? chosen.identity : identity;
320	    const token = openTrackingToken(s.id);
321	    const msg = buildMessage({
322	      identity: sendIdentity,
323	      step: s.step,
324	      contact: s.contact,
325	      sendId: s.id,
326	      footerDisclosure: ctx.footerDisclosure,
327	      track: true,
328	    });
329	
330	    try {
331	      const res = await ctx.transport.send(msg);
332	      const sentAt = new Date();
333	      await db.coldSend.update({
334	        where: { id: s.id },
