1	// Cold Email Engine — send rotation + health-based auto-pause (Phase 3).
2	//
3	// PURE + unit-testable: NO database access, NO I/O. The send worker feeds it the
4	// inbox rows + today's counts and it decides (a) WHICH inbox sends the next
5	// message and (b) WHEN an inbox or a whole domain must auto-pause because its
6	// bounce/complaint rate crossed a burn threshold. Keeping this pure means the
7	// exact rotation + threshold logic the worker runs is what the tests assert.
8	//
9	// Thresholds come from research §4 and default here, but the worker sources the
10	// live values from Settings so an operator can tune them.
11	
12	// ---------------------------------------------------------------------------
13	// Rotation
14	// ---------------------------------------------------------------------------
15	
16	export type InboxStatusLike = "WARMING" | "ACTIVE" | "PAUSED" | "BURNING";
17	
18	/** The minimal inbox shape the rotation engine needs. */
19	export type RotationInbox = {
20	  id: string;
21	  status: InboxStatusLike;
22	  /** Today's allowed volume from the warmup engine (already cap-clamped). */
23	  allowedToday: number;
24	  /** Real sends already made by this inbox today. */
25	  sentToday: number;
26	  /** Domain SPF+DKIM+DMARC all verified? An inbox on an unauthenticated domain never sends. */
27	  authGreen: boolean;
28	  /** Last real send — used to spread load (least-recently-used) + honour the min gap. */
29	  lastSendAt?: Date | string | null;
30	  /** Minimum seconds between sends from this inbox (90–120 typical). */
31	  minGapSeconds?: number;
32	};
33	
34	/** Remaining sends an inbox may still make today (never negative). */
35	export function remainingCapacity(i: RotationInbox): number {
36	  return Math.max(0, Math.floor(i.allowedToday) - Math.floor(i.sentToday));
37	}
38	
39	function toMs(d: Date | string | null | undefined): number | null {
40	  if (!d) return null;
41	  const t = d instanceof Date ? d.getTime() : new Date(d).getTime();
42	  return Number.isFinite(t) ? t : null;
43	}
44	
45	/**
46	 * Is this inbox eligible to send RIGHT NOW? Requires: status ACTIVE (WARMING
47	 * inboxes build reputation but must not carry campaign traffic; PAUSED/BURNING
48	 * never send), the domain authenticated, remaining daily capacity, and at least
49	 * `minGapSeconds` elapsed since its last send.
50	 */
51	export function isInboxEligible(i: RotationInbox, now: Date | number = Date.now()): { eligible: boolean; reason?: string } {
52	  if (i.status !== "ACTIVE") return { eligible: false, reason: `status ${i.status}` };
53	  if (!i.authGreen) return { eligible: false, reason: "domain not authenticated (SPF/DKIM/DMARC)" };
54	  if (remainingCapacity(i) <= 0) return { eligible: false, reason: "daily cap reached" };
55	  const gap = Math.max(0, i.minGapSeconds ?? 0) * 1000;
56	  if (gap > 0) {
57	    const last = toMs(i.lastSendAt);
58	    const nowMs = now instanceof Date ? now.getTime() : now;
59	    if (last !== null && nowMs - last < gap) return { eligible: false, reason: "within min send gap" };
60	  }
61	  return { eligible: true };
62	}
63	
64	/**
65	 * Pick the next inbox to send from among a brand's inboxes: the eligible inbox
66	 * that sent least recently (spreads load, avoids clustering), tie-broken by most
67	 * remaining capacity. Returns null when none are eligible. Note `lastSendAt` here
68	 * is the PERSISTED value — the worker updates it after each send so successive
69	 * calls rotate. The min-gap check uses the same field.
70	 */
71	export function selectNextInbox(inboxes: RotationInbox[], now: Date | number = Date.now()): RotationInbox | null {
72	  const eligible = inboxes.filter((i) => isInboxEligible(i, now).eligible);
73	  if (eligible.length === 0) return null;
74	  eligible.sort((a, b) => {
75	    const la = toMs(a.lastSendAt) ?? 0;
76	    const lb = toMs(b.lastSendAt) ?? 0;
77	    if (la !== lb) return la - lb; // oldest first
78	    return remainingCapacity(b) - remainingCapacity(a); // then most headroom
79	  });
80	  return eligible[0];
81	}
82	
83	/**
84	 * Plan how to distribute `count` sends across a brand's inboxes for a sweep,
85	 * ignoring the time-gap (the worker throttles between sends) but honouring each
86	 * inbox's remaining capacity. Round-robin by remaining capacity so no single
87	 * inbox is drained first. Returns an ordered list of inbox ids (length ≤ count).
88	 * Pure — used by the worker and asserted by tests.
89	 */
90	export function planRotation(inboxes: RotationInbox[], count: number): string[] {
91	  const budget: Record<string, number> = {};
92	  const pool = inboxes.filter((i) => i.status === "ACTIVE" && i.authGreen);
93	  for (const i of pool) budget[i.id] = remainingCapacity(i);
94	  const order: string[] = [];
95	  let remaining = Math.max(0, Math.floor(count));
96	  while (remaining > 0) {
97	    // Pick the inbox with the most remaining budget this round.
98	    let best: string | null = null;
99	    for (const id of Object.keys(budget)) {
100	      if (budget[id] <= 0) continue;
101	      if (best === null || budget[id] > budget[best]) best = id;
102	    }
103	    if (best === null) break; // no capacity anywhere
104	    order.push(best);
105	    budget[best] -= 1;
106	    remaining -= 1;
107	  }
108	  return order;
109	}
110	
111	// ---------------------------------------------------------------------------
112	// Auto-pause thresholds (research §4)
113	// ---------------------------------------------------------------------------
114	
115	export type BurnThresholds = {
116	  /** Pause a single INBOX at/above this bounce rate (per inbox/day). */
117	  bouncePauseInbox: number;
118	  /** Pause the whole DOMAIN when bounce stays at/above this. */
119	  bouncePauseDomain: number;
120	  /** Hard stop + require re-verification at/above this bounce rate. */
121	  bounceHardStop: number;
122	  /** Warn (amber) at/above this bounce rate. */
123	  bounceWarn: number;
124	  /** Pause the whole DOMAIN at/above this complaint rate + flag targeting. */
125	  complaintPauseDomain: number;
126	  /** Warn (amber) at/above this complaint rate. */
127	  complaintWarn: number;
128	};
129	
130	/** Defaults straight from research §4 (auto-pause slightly under the hard ceilings). */
131	export const DEFAULT_THRESHOLDS: BurnThresholds = {
132	  bouncePauseInbox: 0.018, // 1.8%
133	  bouncePauseDomain: 0.02, // 2% sustained
134	  bounceHardStop: 0.05, // 5%
135	  bounceWarn: 0.02, // 2%
136	  complaintPauseDomain: 0.0008, // 0.08%
137	  complaintWarn: 0.0005, // 0.05%
138	};
139	
140	/** Merge partial operator overrides onto the defaults, ignoring bad numbers. */
141	export function resolveThresholds(overrides?: Partial<BurnThresholds> | null): BurnThresholds {
142	  const out = { ...DEFAULT_THRESHOLDS };
143	  if (overrides) {
144	    for (const k of Object.keys(DEFAULT_THRESHOLDS) as (keyof BurnThresholds)[]) {
145	      const v = overrides[k];
146	      if (typeof v === "number" && Number.isFinite(v) && v > 0 && v <= 1) out[k] = v;
147	    }
148	  }
149	  return out;
150	}
151	
152	/** Sent/delivered/bounce/complaint counts over the evaluation window. */
153	export type RateStats = { sent: number; delivered: number; bounces: number; complaints: number };
154	
155	/** bounces ÷ sent (0 when nothing sent). Combines hard+soft — the caller decides which. */
156	export function bounceRate(s: RateStats): number {
157	  return s.sent > 0 ? s.bounces / s.sent : 0;
158	}
159	
160	/** complaints ÷ delivered, falling back to sent when delivered is unknown/zero. */
161	export function complaintRate(s: RateStats): number {
162	  const denom = s.delivered > 0 ? s.delivered : s.sent;
163	  return denom > 0 ? s.complaints / denom : 0;
164	}
165	
166	export type HealthLevel = "healthy" | "warning" | "danger";
167	
168	export type AutoPauseVerdict = {
169	  pause: boolean;
170	  hardStop: boolean;
171	  level: HealthLevel;
172	  reasons: string[];
173	  rules: string[];
174	};
175	
176	const pct = (n: number) => `${(n * 100).toFixed(2)}%`;
177	
178	/**
179	 * Evaluate a single INBOX for auto-pause on bounce rate. `minSends` guards against
180	 * tripping on a handful of sends where a rate is meaningless. A bounce rate at/over
181	 * `bounceHardStop` sets hardStop (pause + require re-verification).
182	 */
183	export function evaluateInboxAutoPause(
184	  stats: RateStats,
185	  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
186	  minSends = 20,
187	): AutoPauseVerdict {
188	  const rules: string[] = [];
189	  const reasons: string[] = [];
190	  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };
191	
192	  const br = bounceRate(stats);
193	  let level: HealthLevel = "healthy";
194	  let pause = false;
195	  let hardStop = false;
196	
197	  if (br >= thresholds.bounceHardStop) {
198	    pause = true;
199	    hardStop = true;
200	    level = "danger";
201	    rules.push("bounce_hard_stop");
202	    reasons.push(`Bounce rate ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — paused, re-verify the list`);
203	  } else if (br >= thresholds.bouncePauseInbox) {
204	    pause = true;
205	    level = "danger";
206	    rules.push("bounce_pause_inbox");
207	    reasons.push(`Bounce rate ${pct(br)} ≥ inbox pause ${pct(thresholds.bouncePauseInbox)} — inbox paused`);
208	  } else if (br >= thresholds.bounceWarn) {
209	    level = "warning";
210	    rules.push("bounce_warn");
211	    reasons.push(`Bounce rate ${pct(br)} approaching the ceiling`);
212	  }
213	  return { pause, hardStop, level, reasons, rules };
214	}
215	
216	/**
217	 * Evaluate a whole DOMAIN for auto-pause on bounce AND complaint rate. A domain
218	 * pauses when its aggregate bounce is sustained over the domain threshold or its
219	 * complaint rate crosses the pause line (wrong ICP / deceptive copy) — because a
220	 * single burned domain poisons every recipient on it.
221	 */
222	export function evaluateDomainAutoPause(
223	  stats: RateStats,
224	  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
225	  minSends = 50,
226	): AutoPauseVerdict {
227	  const rules: string[] = [];
228	  const reasons: string[] = [];
229	  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };
230	
231	  const br = bounceRate(stats);
232	  const cr = complaintRate(stats);
233	  let level: HealthLevel = "healthy";
234	  let pause = false;
235	  let hardStop = false;
236	
237	  if (br >= thresholds.bounceHardStop) {
238	    pause = true;
239	    hardStop = true;
240	    level = "danger";
241	    rules.push("bounce_hard_stop");
242	    reasons.push(`Domain bounce ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — domain stopped, re-verify`);
243	  } else if (br >= thresholds.bouncePauseDomain) {
244	    pause = true;
245	    level = "danger";
246	    rules.push("bounce_pause_domain");
247	    reasons.push(`Domain bounce ${pct(br)} ≥ domain pause ${pct(thresholds.bouncePauseDomain)} — domain paused`);
248	  }
249	
250	  if (cr >= thresholds.complaintPauseDomain) {
251	    pause = true;
252	    level = "danger";
253	    rules.push("complaint_pause_domain");
254	    reasons.push(`Complaint rate ${pct(cr)} ≥ ${pct(thresholds.complaintPauseDomain)} — domain paused, review targeting`);
255	  } else if (cr >= thresholds.complaintWarn && level === "healthy") {
256	    level = "warning";
257	    rules.push("complaint_warn");
258	    reasons.push(`Complaint rate ${pct(cr)} approaching the ceiling`);
259	  }
260	
261	  if (level === "healthy" && br >= thresholds.bounceWarn) {
262	    level = "warning";
263	    rules.push("bounce_warn");
264	  }
265	  return { pause, hardStop, level, reasons, rules };
266	}
