1	// Cold Email Engine — deliverability analytics (Phase 3).
2	//
3	// PURE + unit-testable: NO database access, NO I/O. Turns raw event counts into
4	// the derived rates the dashboards show, and — critically — encodes the 2026
5	// HONESTY posture about open tracking:
6	//
7	//   Apple Mail Privacy Protection pre-loads tracking pixels on Apple's servers,
8	//   so 50%+ of "opens" are machine-generated. Open rate is therefore surfaced but
9	//   flagged UNRELIABLE and MUST NOT be a health signal or optimization target.
10	//   The primary signals are reply / positive-reply, bounce, complaint, click,
11	//   unsubscribe, and inbox-placement (from seed tests).
12	//
13	// The worker rolls DeliverabilityEvent rows into MetricsDaily; this module derives
14	// the rates from those counts and colours them against the research benchmarks.
15	
16	// ---------------------------------------------------------------------------
17	// Counts + derived rates
18	// ---------------------------------------------------------------------------
19	
20	/** Raw daily counts for one scope (campaign / inbox / domain / brand). */
21	export type MetricCounts = {
22	  sent: number;
23	  delivered: number;
24	  hardBounce: number;
25	  softBounce: number;
26	  /** UNRELIABLE — MPP/scanner-inflated. Never a health signal. */
27	  opens: number;
28	  uniqueClicks: number;
29	  replies: number;
30	  positiveReplies: number;
31	  complaints: number;
32	  unsubscribes: number;
33	};
34	
35	export const ZERO_COUNTS: MetricCounts = {
36	  sent: 0,
37	  delivered: 0,
38	  hardBounce: 0,
39	  softBounce: 0,
40	  opens: 0,
41	  uniqueClicks: 0,
42	  replies: 0,
43	  positiveReplies: 0,
44	  complaints: 0,
45	  unsubscribes: 0,
46	};
47	
48	export type DerivedRates = {
49	  deliveryRate: number;
50	  bounceRate: number; // (hard+soft)/sent
51	  hardBounceRate: number;
52	  complaintRate: number; // complaints/delivered
53	  unsubRate: number;
54	  clickRate: number;
55	  replyRate: number;
56	  positiveReplyRate: number;
57	  /** UNRELIABLE — surfaced for context only, flagged everywhere it appears. */
58	  openRate: number;
59	};
60	
61	const safeDiv = (a: number, b: number) => (b > 0 ? a / b : 0);
62	
63	/** Add two count buckets — used when rolling many event rows into one daily row. */
64	export function addCounts(a: MetricCounts, b: Partial<MetricCounts>): MetricCounts {
65	  const out = { ...a };
66	  for (const k of Object.keys(ZERO_COUNTS) as (keyof MetricCounts)[]) {
67	    out[k] = (a[k] ?? 0) + (b[k] ?? 0);
68	  }
69	  return out;
70	}
71	
72	/**
73	 * Derive every rate from a count bucket. Delivered is the denominator for the
74	 * engagement/complaint rates (they only make sense over accepted mail); bounce is
75	 * over sent. Divide-by-zero is 0, never NaN.
76	 */
77	export function deriveRates(m: MetricCounts): DerivedRates {
78	  const bounces = (m.hardBounce ?? 0) + (m.softBounce ?? 0);
79	  return {
80	    deliveryRate: safeDiv(m.delivered, m.sent),
81	    bounceRate: safeDiv(bounces, m.sent),
82	    hardBounceRate: safeDiv(m.hardBounce, m.sent),
83	    complaintRate: safeDiv(m.complaints, m.delivered),
84	    unsubRate: safeDiv(m.unsubscribes, m.delivered),
85	    clickRate: safeDiv(m.uniqueClicks, m.delivered),
86	    replyRate: safeDiv(m.replies, m.delivered),
87	    positiveReplyRate: safeDiv(m.positiveReplies, m.delivered),
88	    openRate: safeDiv(m.opens, m.delivered),
89	  };
90	}
91	
92	// ---------------------------------------------------------------------------
93	// Open-rate honesty (surfaced by every UI that shows an open number)
94	// ---------------------------------------------------------------------------
95	
96	export const OPEN_RATE_UNRELIABLE = true;
97	export const OPEN_RATE_LABEL = "Open rate (unreliable)";
98	export const OPEN_RATE_WARNING =
99	  "Unreliable (MPP-inflated) — do not optimize on this. Apple Mail Privacy Protection auto-opens 50%+ of email and corporate scanners pre-fetch pixels, so opens are machine-generated noise.";
100	
101	/** The signals leaders actually optimise on in 2026 (research §4). */
102	export const PRIMARY_SIGNALS = [
103	  "positiveReplyRate",
104	  "replyRate",
105	  "bounceRate",
106	  "complaintRate",
107	  "clickRate",
108	  "unsubRate",
109	  "inboxPlacementRate",
110	] as const;
111	
112	// ---------------------------------------------------------------------------
113	// Benchmark bands (research §4) → red/amber/green
114	// ---------------------------------------------------------------------------
115	
116	export type Band = "green" | "amber" | "red";
117	
118	/** Bounce: <2% green · 2–5% amber · >5% red (research §4). */
119	export function bounceBand(rate: number): Band {
120	  if (rate < 0.02) return "green";
121	  if (rate < 0.05) return "amber";
122	  return "red";
123	}
124	
125	/** Complaint: <0.05% green · 0.05–0.08% amber · >0.08% red (research §4). */
126	export function complaintBand(rate: number): Band {
127	  if (rate < 0.0005) return "green";
128	  if (rate < 0.0008) return "amber";
129	  return "red";
130	}
131	
132	/** Inbox placement: ≥90% green · 80–90% amber · <80% red (research §4). */
133	export function placementBand(rate: number): Band {
134	  if (rate >= 0.9) return "green";
135	  if (rate >= 0.8) return "amber";
136	  return "red";
137	}
138	
139	// ---------------------------------------------------------------------------
140	// Inbox-placement (seed test) result
141	// ---------------------------------------------------------------------------
142	
143	export type PlacementResult = {
144	  inboxPct: number;
145	  spamPct: number;
146	  promotionsPct: number;
147	  missingPct: number;
148	};
149	
150	/** Normalise seed-test percentages to fractions summing ≤1 (defensive). */
151	export function normalizePlacement(p: Partial<PlacementResult>): PlacementResult {
152	  const f = (v: unknown) => {
153	    let n = Number(v);
154	    if (!Number.isFinite(n) || n < 0) n = 0;
155	    if (n > 1) n = n / 100; // accept whole-percent inputs
156	    return Math.min(1, n);
157	  };
158	  return {
159	    inboxPct: f(p.inboxPct),
160	    spamPct: f(p.spamPct),
161	    promotionsPct: f(p.promotionsPct),
162	    missingPct: f(p.missingPct),
163	  };
164	}
165	
166	// ---------------------------------------------------------------------------
167	// Composite health score (0–100) — deliberately excludes open rate
168	// ---------------------------------------------------------------------------
169	
170	/**
171	 * A 0–100 health score from the MPP-proof signals only: bounce, complaint and
172	 * unsubscribe penalise; a healthy reply rate lifts. Opens are NEVER an input —
173	 * that is the whole point. Placement (when known) pulls the score toward the
174	 * seed-test truth. Returns 100 when there is no volume to judge.
175	 */
176	export function healthScore(m: MetricCounts, placement?: PlacementResult | null): number {
177	  if (m.sent <= 0) return 100;
178	  const r = deriveRates(m);
179	  let score = 100;
180	  // Bounce: every 1% over 0 costs ~12 points (5% ≈ -60).
181	  score -= Math.min(60, (r.bounceRate / 0.01) * 12);
182	  // Complaint: brutal — 0.1% ≈ -30, 0.3% ≈ -90.
183	  score -= Math.min(90, (r.complaintRate / 0.001) * 30);
184	  // Unsubscribe: mild disengagement signal.
185	  score -= Math.min(15, (r.unsubRate / 0.01) * 5);
186	  // Reply rate rewards genuine engagement (cap +10).
187	  score += Math.min(10, (r.replyRate / 0.02) * 5);
188	  if (placement) {
189	    // Blend 30% toward measured inbox placement when we have a seed test.
190	    score = score * 0.7 + placement.inboxPct * 100 * 0.3;
191	  }
192	  return Math.max(0, Math.min(100, Math.round(score)));
193	}
194	
195	export type HealthLevel = "healthy" | "warning" | "danger";
196	
197	/** Map a composite health score to a status band for badges/colours. */
198	export function healthLevel(score: number): HealthLevel {
199	  if (score >= 75) return "healthy";
200	  if (score >= 50) return "warning";
201	  return "danger";
202	}
203	
204	/** Format a fraction as a percent string for display (e.g. 0.0123 → "1.23%"). */
205	export function formatPct(rate: number, dp = 2): string {
206	  if (!Number.isFinite(rate)) return "—";
207	  return `${(rate * 100).toFixed(dp)}%`;
208	}
