1	// Cold Email Engine — warmup engine (Phase 3).
2	//
3	// PURE + unit-testable: NO database access, NO I/O, NO network. The warmup
4	// worker step and the Warming UI both call these functions, and the test suite
5	// (test/coldemail-phase3.test.ts) exercises the ramp math directly.
6	//
7	// What "warming" means here (per the 2026 research): a brand-new inbox starts at
8	// a handful of sends/day and ramps to a safe ceiling over 2–4 weeks so the
9	// mailbox provider builds a history of trusted, low-and-slow sending before any
10	// real campaign volume. This module computes the ALLOWED volume for an inbox on
11	// a given day — it never sends anything.
12	//
13	// Honesty note baked into the design (research §2): we favour REAL-engagement
14	// warmup (genuine replies + spam-rescue on a vetted seed) over a synthetic
15	// auto-open pool, because Gmail/Yahoo increasingly detect and penalise synthetic
16	// warmup patterns. A synthetic warmup NETWORK that sends real mail between pooled
17	// mailboxes is deliberately OUT OF SCOPE (SaaS-pool territory) — see WARMUP_MODES.
18	
19	import { warmupDayIndex } from "@/lib/coldemail/compliance";
20	
21	export type WarmupStrategyKey = "CONSERVATIVE" | "STANDARD" | "AGGRESSIVE" | "ADAPTIVE";
22	export type WarmupModeKey = "POOL" | "REAL_SEED" | "HYBRID";
23	
24	/** A warmup ramp definition: from `startCap`/day up to `targetCap`/day over `rampDays`. */
25	export type WarmupPlan = {
26	  startCap: number;
27	  targetCap: number;
28	  rampDays: number;
29	};
30	
31	/**
32	 * Consensus 2026 ramp presets (research §2). New inbox ≈5–10/day → 30–50/day over
33	 * 2–4 weeks. AGGRESSIVE mirrors "pre-warmed inbox" guidance (start higher, ramp
34	 * faster) and should only be used on inboxes with prior sending history.
35	 */
36	export const WARMUP_PRESETS: Record<WarmupStrategyKey, WarmupPlan> = {
37	  CONSERVATIVE: { startCap: 5, targetCap: 30, rampDays: 28 },
38	  STANDARD: { startCap: 5, targetCap: 40, rampDays: 21 },
39	  AGGRESSIVE: { startCap: 10, targetCap: 50, rampDays: 14 },
40	  ADAPTIVE: { startCap: 5, targetCap: 40, rampDays: 21 },
41	};
42	
43	/**
44	 * Warmup modes and their honesty posture. The default is HYBRID/REAL_SEED; POOL
45	 * (synthetic auto-opens between simulated inboxes) carries an explicit warning
46	 * because it can be detected and hurt deliverability in 2026.
47	 */
48	export const WARMUP_MODES: Record<WarmupModeKey, { label: string; safe: boolean; note: string }> = {
49	  REAL_SEED: {
50	    label: "Real seed",
51	    safe: true,
52	    note: "Genuine replies + spam-rescue from a small vetted seed audience. Safest posture in 2026.",
53	  },
54	  HYBRID: {
55	    label: "Hybrid",
56	    safe: true,
57	    note: "Mostly real-engagement with limited pooled signals. Recommended default.",
58	  },
59	  POOL: {
60	    label: "Synthetic pool",
61	    safe: false,
62	    note: "Artificial opens/replies between simulated inboxes. Gmail/Yahoo increasingly detect this and it can DAMAGE deliverability. A real shared warmup network cannot be self-hosted (SaaS-pool territory) — out of scope.",
63	  },
64	};
65	
66	/** Clamp a plan into sane bounds so bad input can never produce an uncapped ramp. */
67	export function normalizePlan(plan: Partial<WarmupPlan> | null | undefined): WarmupPlan {
68	  const startCap = clampInt(plan?.startCap, 1, 200, 5);
69	  const targetCap = clampInt(plan?.targetCap, startCap, 500, Math.max(startCap, 40));
70	  const rampDays = clampInt(plan?.rampDays, 1, 90, 21);
71	  return { startCap, targetCap, rampDays };
72	}
73	
74	function clampInt(v: unknown, min: number, max: number, fallback: number): number {
75	  const n = Math.floor(Number(v));
76	  if (!Number.isFinite(n)) return fallback;
77	  return Math.min(max, Math.max(min, n));
78	}
79	
80	/**
81	 * The allowed daily volume for an inbox on warmup `dayIndex` (0-based: day 0 = the
82	 * first day → startCap). Linear ramp from startCap to targetCap across rampDays;
83	 * clamps to targetCap once the ramp completes. Deterministic and pure.
84	 */
85	export function warmupDailyLimit(dayIndex: number, plan: WarmupPlan): number {
86	  const p = normalizePlan(plan);
87	  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
88	  if (day <= 0) return p.startCap;
89	  if (day >= p.rampDays) return p.targetCap;
90	  const ramped = p.startCap + (p.targetCap - p.startCap) * (day / p.rampDays);
91	  return Math.min(p.targetCap, Math.max(p.startCap, Math.round(ramped)));
92	}
93	
94	/** Has the inbox finished its ramp (reached targetCap)? */
95	export function isWarmupComplete(dayIndex: number, plan: WarmupPlan): boolean {
96	  const p = normalizePlan(plan);
97	  return (Number.isFinite(dayIndex) ? Math.floor(dayIndex) : 0) >= p.rampDays;
98	}
99	
100	/**
101	 * ADAPTIVE back-off: when an inbox's health score dips, shrink today's allowance
102	 * rather than pushing full ramp volume through a struggling inbox (research §2/§4
103	 * "adaptive ramp down on soft-bounce spikes"). Healthy (≥80) → no change;
104	 * 60–79 → half; <60 → quarter. Never drops below 1.
105	 */
106	export function applyHealthBackoff(limit: number, healthScore: number): number {
107	  const h = Number.isFinite(healthScore) ? healthScore : 100;
108	  const base = Math.max(0, Math.floor(limit));
109	  if (h >= 80) return base;
110	  if (h >= 60) return Math.max(1, Math.round(base * 0.5));
111	  return Math.max(1, Math.round(base * 0.25));
112	}
113	
114	export type AllowedVolumeOpts = {
115	  warmupStartedAt?: Date | string | null;
116	  plan: WarmupPlan;
117	  /** Absolute per-inbox ceiling — the warmup ramp is additionally clamped by this. */
118	  dailyCap?: number;
119	  /** For ADAPTIVE: the inbox health score (0–100). */
120	  healthScore?: number;
121	  adaptive?: boolean;
122	  now?: Date | number;
123	};
124	
125	/**
126	 * Today's allowed send volume for an inbox: the warmup ramp value for the current
127	 * warmup day, clamped by the inbox's absolute dailyCap, with an optional adaptive
128	 * health back-off. `warmupStartedAt = null` means the inbox is on day 0 (never
129	 * uncapped). This is the single number the rotation engine budgets against.
130	 */
131	export function inboxAllowedVolume(opts: AllowedVolumeOpts): number {
132	  const plan = normalizePlan(opts.plan);
133	  const day = warmupDayIndex(opts.warmupStartedAt ?? null, opts.now ?? Date.now());
134	  let limit = warmupDailyLimit(day, plan);
135	  if (opts.adaptive) limit = applyHealthBackoff(limit, opts.healthScore ?? 100);
136	  const cap = opts.dailyCap && opts.dailyCap > 0 ? Math.floor(opts.dailyCap) : plan.targetCap;
137	  return Math.max(0, Math.min(limit, cap));
138	}
139	
140	/** The planned-ramp curve (day → planned volume) for charting the warmup. */
141	export function warmupRampCurve(plan: WarmupPlan): { day: number; planned: number }[] {
142	  const p = normalizePlan(plan);
143	  const out: { day: number; planned: number }[] = [];
144	  for (let d = 0; d <= p.rampDays; d++) out.push({ day: d, planned: warmupDailyLimit(d, p) });
145	  return out;
146	}
147	
148	export type WarmupStatus = {
149	  complete: boolean;
150	  day: number;
151	  rampDays: number;
152	  currentLimit: number;
153	  targetCap: number;
154	  label: string;
155	};
156	
157	/**
158	 * A plain-language warmup status for the UI: "Warming — day 9 of 21, ramping to
159	 * 40/day" or "Warmed — sending up to 40/day". `dayIndex` is 0-based; the label
160	 * shows 1-based days so a human reads "day 1" on the first day.
161	 */
162	export function warmupStatus(dayIndex: number, plan: WarmupPlan): WarmupStatus {
163	  const p = normalizePlan(plan);
164	  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
165	  const complete = day >= p.rampDays;
166	  const currentLimit = warmupDailyLimit(day, p);
167	  const label = complete
168	    ? `Warmed — sending up to ${p.targetCap}/day`
169	    : `Warming — day ${day + 1} of ${p.rampDays}, ramping to ${p.targetCap}/day (today ${currentLimit})`;
170	  return { complete, day, rampDays: p.rampDays, currentLimit, targetCap: p.targetCap, label };
171	}
