226	/**
227	 * Paste-a-CSV import. Parses server-side and creates Business (+ optional
228	 * Contact) rows. No scraping, no enrichment — exactly the rows pasted. Contacts
229	 * de-dupe against the unique email. Returns a summary in the error/ok channel.
230	 */
231	export async function importBusinessesCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
232	  await requireArea("platform");
233	
234	  const csv = String(formData.get("csv") ?? "");
235	  const recordConsentAll = formData.get("recordConsent") === "on" || formData.get("recordConsent") === "true";
236	  if (!csv.trim()) return { error: "Paste some CSV rows first." };
237	
238	  const { headers, rows } = parseCsv(csv);
239	  if (headers.length === 0 || rows.length === 0) {
240	    return { error: "Could not find a header row and at least one data row." };
241	  }
242	  const cols = headers.map((h) => HEADER_ALIASES[h] ?? "");
243	  if (!cols.includes("name")) {
244	    return { error: "CSV needs at least a 'name' (business name) column." };
245	  }
246	
247	  let created = 0;
248	  let contactsCreated = 0;
249	  let skipped = 0;
250	
251	  for (const r of rows) {
252	    const rec: Record<string, string> = {};
253	    cols.forEach((field, i) => {
254	      if (field) rec[field] = (r[i] ?? "").trim();
255	    });
256	    const name = (rec.name ?? "").trim();
257	    if (!name) {
258	      skipped++;
259	      continue;
260	    }
261	    try {
262	      const business = await db.business.create({
263	        data: {
264	          name: name.slice(0, 160),
265	          category: (rec.category ?? "").slice(0, 120),
266	          businessType: (rec.businessType ?? "").slice(0, 120),
267	          website: (rec.website ?? "").slice(0, 200),
268	          phone: (rec.phone ?? "").slice(0, 60),
269	          addressLine: (rec.addressLine ?? "").slice(0, 200),
270	          city: (rec.city ?? "").slice(0, 120),
271	          region: (rec.region ?? "").slice(0, 120),
272	          country: (rec.country ?? "").slice(0, 120),
273	          companySize: (rec.companySize ?? "").slice(0, 60),
274	          source: "csv",
275	        },
276	      });
277	      created++;
278	
279	      const email = normalizeEmail(rec.email);
280	      if (email && emailSchema.safeParse(email).success) {
281	        const clash = await db.contact.findUnique({ where: { email }, select: { id: true } });
282	        if (!clash) {
283	          const contact = await db.contact.create({
284	            data: {
285	              businessId: business.id,
286	              fullName: (rec.fullName ?? "").slice(0, 160),
287	              title: (rec.title ?? "").slice(0, 120),
288	              email,
289	            },
290	          });
291	          contactsCreated++;
292	          if (recordConsentAll) {
293	            await db.consentRecord.create({
294	              data: { contactId: contact.id, basis: "LEGITIMATE_INTEREST", source: "csv import" },
295	            });
296	          }
297	        }
298	      }
299	    } catch (err) {
300	      await logEvent("error", "coldemail.business.import", { message: String(err) });
301	      skipped++;
302	    }
303	  }
304	
305	  revalidatePath("/admin/coldemail/businesses");
306	  revalidatePath("/admin/coldemail");
307	  return { ok: true, error: `Imported ${created} businesses and ${contactsCreated} contacts. ${skipped} row(s) skipped.` };
308	}
