584	// ---------------------------------------------------------------------------
585	// Campaign dry-run / preview — computes recipient breakdown WITHOUT sending.
586	// ---------------------------------------------------------------------------
587	
588	export type CampaignPreview = {
589	  blocked: boolean;
590	  missingRequirements: string[];
591	  total: number;
592	  suppressed: number;
593	  /** Non-mailable: dead / hard-bounced / complained / unsubscribed / invalid. */
594	  dead: number;
595	  /** Already contacted at least once (informational — still sendable if mailable). */
596	  alreadyEmailed: number;
597	  missingConsent: number;
598	  sendable: number;
599	};
600	
601	/**
602	 * Dry-run a DRAFT campaign: for its list, how many recipients would be
603	 * SUPPRESSED, how many lack a recorded consent basis, and how many are
604	 * sendable — WITHOUT sending, scheduling, or writing anything. Blocked (with the
605	 * missing-requirement list) if the brand fails requireBrandCompliance.
606	 */
607	export async function previewCampaign(campaignId: string): Promise<CampaignPreview | { error: string }> {
608	  await requireArea("platform");
609	
610	  const campaign = await db.coldCampaign.findUnique({
611	    where: { id: campaignId },
612	    include: { brand: true },
613	  });
614	  if (!campaign) return { error: "Campaign not found." };
615	
616	  const missing = requireBrandCompliance(campaign.brand);
617	  if (missing.length > 0) {
618	    return {
619	      blocked: true,
620	      missingRequirements: missing.map((m) => m.label),
621	      total: 0,
622	      suppressed: 0,
623	      dead: 0,
624	      alreadyEmailed: 0,
625	      missingConsent: 0,
626	      sendable: 0,
627	    };
628	  }
629	
630	  const members = await db.emailListMember.findMany({
631	    where: { listId: campaign.listId },
632	    select: {
633	      contact: {
634	        select: {
635	          id: true,
636	          email: true,
637	          emailStatus: true,
638	          timesEmailed: true,
639	          consentRecords: { select: { id: true }, take: 1 },
640	        },
641	      },
642	    },
643	  });
644	
645	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
646	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
647	    select: { email: true, domain: true, scope: true, brandId: true },
648	  });
649	
650	  let suppressed = 0;
651	  let dead = 0;
652	  let alreadyEmailed = 0;
653	  let missingConsent = 0;
654	  let sendable = 0;
655	  for (const m of members) {
656	    const email = m.contact.email;
657	    if ((m.contact.timesEmailed ?? 0) > 0) alreadyEmailed++;
658	    // Exclusion order: suppressed → dead status → missing consent → sendable.
659	    if (isSuppressed(email, campaign.brandId, suppressions)) {
660	      suppressed++;
661	      continue;
662	    }
663	    if (!isMailableStatus(m.contact.emailStatus)) {
664	      dead++;
665	      continue;
666	    }
667	    if (m.contact.consentRecords.length === 0) {
668	      missingConsent++;
669	      continue;
670	    }
671	    sendable++;
672	  }
673	
674	  return {
675	    blocked: false,
676	    missingRequirements: [],
677	    total: members.length,
678	    suppressed,
679	    dead,
680	    alreadyEmailed,
681	    missingConsent,
682	    sendable,
683	  };
684	}
