81	      emailStatus: t.emailStatus as never,
82	      bounceCount: t.bounceCount,
83	      ...(t.stampBounceAt ? { lastBounceAt: new Date() } : {}),
84	      ...(t.dead ? { deadAt: new Date(), ...(t.deadReason ? { deadReason: t.deadReason } : {}) } : {}),
85	    },
86	  });
87	
88	  return { suppress: t.suppress, suppressReason: t.suppressReason, dead: t.dead };
89	}
90	
91	/**
92	 * Look back this far when computing a brand's complaint rate. A rolling window
93	 * keeps one bad historical week from pinning the brand paused forever once hygiene
94	 * recovers.
95	 */
96	const COMPLAINT_WINDOW_DAYS = 30;
97	
98	/** Don't trip the breaker until there's enough volume for a rate to be meaningful. */
99	const COMPLAINT_MIN_SENDS = 50;
100	
101	/**
102	 * Record a bounce or complaint for an address: write a GLOBAL Suppression (so no
103	 * brand ever re-contacts it), attach the matching EmailEvent to the most recent
104	 * send if we can find one, and — for complaints — run the circuit breaker.
105	 *
106	 * Idempotent on the suppression (check-then-insert on the GLOBAL row). Never
107	 * throws to the caller — feedback ingestion must not fail a webhook.
108	 */
109	export async function recordFeedback(
110	  rawEmail: string,
111	  kind: FeedbackKind,
112	  opts: { brandId?: string | null; note?: string } = {},
113	): Promise<{ ok: boolean; suppressed: boolean; brandPaused?: boolean }> {
114	  const email = normalizeEmail(rawEmail);
115	  if (!email || !email.includes("@")) return { ok: false, suppressed: false };
116	
117	  const { eventType } = resolveKind(kind);
118	
119	  try {
120	    // 1) Run the "bounce → dead" pipeline on the contact (if we have one). This
121	    //    transitions emailStatus/bounceCount/deadAt and TELLS US whether to
122	    //    suppress — a SOFT bounce below the dead threshold must NOT suppress (it's
123	    //    transient and still retryable).
124	    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
125	    let suppress = true;
126	    let suppressReason: SuppressReason = kind === "COMPLAINT" ? "COMPLAINT" : kind === "UNSUBSCRIBE" ? "UNSUBSCRIBE" : "BOUNCE";
127	    if (contact) {
128	      const h = await applyContactHygiene(contact.id, kind, opts.note);
129	      suppress = h.suppress;
130	      suppressReason = h.suppressReason ?? suppressReason;
131	    } else {
132	      // No contact row to track soft-bounce state — only suppress terminal signals.
133	      suppress = kind !== "SOFT_BOUNCE";
134	    }
135	
136	    // 2) GLOBAL suppression (idempotent), ONLY when the transition demands it. A
137	    //    dead/complained/unsubscribed address stays bad for every brand.
138	    if (suppress) {
139	      const existing = await db.suppression.findFirst({ where: { email, scope: "GLOBAL" }, select: { id: true } });
140	      if (!existing) {
141	        await db.suppression.create({ data: { email, scope: "GLOBAL", reason: suppressReason } });
142	      }
143	    }
144	
145	    // 3) Attach an event to the latest send to this address, if one exists, so the
146	    //    campaign stats reflect the bounce/complaint.
147	    let brandId = opts.brandId ?? null;
148	    if (contact) {
149	      const lastSend = await db.coldSend.findFirst({
150	        where: { contactId: contact.id },
151	        orderBy: { createdAt: "desc" },
152	        select: { id: true, campaign: { select: { brandId: true } } },
153	      });
154	      if (lastSend) {
155	        await db.emailEvent.create({
156	          data: { sendId: lastSend.id, type: eventType, meta: (opts.note ?? "").slice(0, 300) },
157	        });
158	        brandId = brandId ?? lastSend.campaign.brandId;
159	      }
160	    }
161	
162	    // 4) Complaint circuit breaker.
163	    let brandPaused = false;
164	    if (kind === "COMPLAINT" && brandId) {
165	      brandPaused = await maybeTripCircuitBreaker(brandId);
166	    }
167	
168	    return { ok: true, suppressed: suppress, brandPaused };
169	  } catch (err) {
170	    await logEvent("error", "coldemail.feedback.record", { message: String(err), kind, email });
171	    return { ok: false, suppressed: false };
172	  }
173	}
174	
175	/** Sends + complaints for a brand over the rolling window. */
176	export async function complaintStats(brandId: string): Promise<{ sends: number; complaints: number; rate: number }> {
177	  const since = new Date(Date.now() - COMPLAINT_WINDOW_DAYS * 86_400_000);
178	  const sends = await db.coldSend.count({
179	    where: { campaign: { brandId }, sentAt: { gte: since } },
180	  });
181	  const complaints = await db.emailEvent.count({
182	    where: { type: "COMPLAINT", createdAt: { gte: since }, send: { campaign: { brandId } } },
183	  });
184	  const rate = sends > 0 ? complaints / sends : 0;
185	  return { sends, complaints, rate };
186	}
187	
188	/**
189	 * Pause the brand if its complaint rate is over the configured threshold and it
190	 * has enough volume to matter. Returns whether it ended up paused. This is what
191	 * stops one bad campaign from taking down all three brands' shared reputation.
192	 */
193	export async function maybeTripCircuitBreaker(brandId: string): Promise<boolean> {
194	  const threshold = Number(await getSetting("coldemail_complaint_threshold")) || 0.003;
195	  const { sends, complaints, rate } = await complaintStats(brandId);
196	  if (sends < COMPLAINT_MIN_SENDS) return false;
197	  if (rate < threshold) return false;
198	
199	  const brand = await db.brand.findUnique({ where: { id: brandId }, select: { sendingPaused: true } });
200	  if (brand?.sendingPaused) return true; // already paused
201	
202	  await db.brand.update({
203	    where: { id: brandId },
204	    data: {
205	      sendingPaused: true,
206	      pausedReason: `Complaint rate ${(rate * 100).toFixed(2)}% (${complaints}/${sends}) exceeded ${(threshold * 100).toFixed(2)}% — auto-paused`,
207	    },
208	  });
209	  await logEvent("warn", "coldemail.circuit_breaker.trip", { brandId, rate, complaints, sends, threshold });
210	  return true;
211	}
212	
213	/** Manually clear a brand's circuit-breaker pause (operator action after cleanup). */
214	export async function clearCircuitBreaker(brandId: string): Promise<void> {
215	  await db.brand.update({ where: { id: brandId }, data: { sendingPaused: false, pausedReason: "" } });
216	}
217	
218	/** Manual bulk suppression helper for a domain (e.g. a whole company complained). */
219	export async function suppressDomain(rawDomain: string, reason: FeedbackKind): Promise<boolean> {
220	  const domain = normalizeDomain(rawDomain);
221	  if (!domain || !domain.includes(".")) return false;
222	  const supReason: SuppressReason = reason === "COMPLAINT" ? "COMPLAINT" : reason === "UNSUBSCRIBE" ? "UNSUBSCRIBE" : "BOUNCE";
223	  const existing = await db.suppression.findFirst({ where: { domain, scope: "GLOBAL" }, select: { id: true } });
224	  if (!existing) await db.suppression.create({ data: { domain, scope: "GLOBAL", reason: supReason } });
225	  return true;
226	}
